#!/usr/bin/env bash
# B3c = B3a with ONE factor changed: --consistency_lambda 0.3 -> 1.0 (JS consistency dose step; everything else identical to B3a, incl. --consistency js --consistency_pairs both --batch_size 8)
#   generated by exploop (wave B3, iteration 3) from exploop/B3/iter03/design.result.json
#  B3c = B3a with one flag changed: --consistency_lambda 1.0, up from 0.3. This is the JS
#    consistency dose step. Everything else is identical to B3a: - --consistency js
#    --consistency_pairs both; - --batch_size 8 = 8 pairs = 16 clips/step; - 8 epochs, LR 2.5e-6
#    warmup-cosine to 5e-7, the same 75792 steps; - sampler shuffle, CE weights 0.1 0.9; - RTC aug
#    + MUSAN, loudness norm -23. It runs ~8 h. Evidence: - B3a, consistency at lambda 0.3, is the
#    only above-band gain of the wave: merge half_B 93.06 against B2f 91.98, noisy EER 10.09 ->
#    9.16. Its JS term was only 2.5-4.5 % of the train loss (B3a metrics.jsonl), and the report
#    could not tell whether the gain came from the divergence weight or from the doubled steps /
#    two views. - B3b, the balanced sampler, was negative at -0.83 [-1.46, -0.25]. It ruled out
#    exposure and the operating point as the cause of the residual error. Target: confident noisy
#    bona false alarms, a ranking error. On the B3a merge, 180 of 782 half_B noisy bona are false
#    alarms, 77 % of them at p_spoof >= 0.99, and English carries 91 of the 180. Rule against
#    B3a-top5 = 93.06 on half_B: promote if the delta is > +0.5, the CI excludes 0 and the clean
#    drop is <= 0.5; null within +-0.5; negative below -0.5. A null delta with noisy EER within
#    +-0.3 of 9.16 means the JS weight is not the active ingredient (keep 0.3).
#  Why: The B3b report gives the largest remaining error in §5.4, §7 and largest_remaining_error:
#    confident noisy bona false alarms. On the B3a merge, which is still the reference, 180 of 782
#    half_B noisy bona are false alarms and 77 % of them sit at p_spoof >= 0.99. English carries 91
#    of the 180. B3b ruled out two explanations. It is not exposure: the balanced sampler made
#    English worse, with 13 fixed against 50 broken. It is not the operating point: B3a's merge is
#    already optimal at 0.5, with the best global logit at -0.15 and only 0.02 recoverable. What
#    remains is a ranking / generalisation error, and the only lever in this wave that has improved
#    ranking is consistency. It took merge noisy EER from 10.09 to 9.16 against B2f. Why this lever
#    is allowed: - The wave.json lever_queue lists consistency_dose first, with the condition "if
#    B3a's consistency helps". B3a was positive / promote, so the condition holds. - The skill
#    allows a dose step of a clearly positive lever. - The plan snapshot lists "a dose step:
#    --consistency_lambda 1.0" under "If consistency helps". - The analyst ranked it first after
#    B3b. The B3a report (§5, line 334) records a confound that matters for the full-run recipe.
#    B3a doubled the steps, showed each clip in two views and added the JS term, which was only
#    2.5-4.5 % of the train loss (computed in the derivation). That run cannot say which of the
#    three produced its +1.08. This dose step changes one flag and keeps steps, views, batch and
#    schedule identical, so it isolates the divergence weight. At lambda 1.0 the JS term would be
#    about 8-13.5 % of the loss at B3a's CE/JS values: a real increase that is still far below
#    AugMix-style weights. It is one flag inside the consistency coupled group. --batch_size 8 is
#    unchanged, as lever_notes require. Nothing forbidden or fixed is touched, and the run stays at
#    8 of max 10 epochs. Why not the alternatives: - SpecAugment (rank 2) targets over-fitting, a
#    secondary symptom. The saturated noisy core is the dominant error. - --aug_snr_db 0 20 and
#    --aug_codec_profiles random target narrower slices: SNR 0 (EER 14.67 / 15.08) and g726/gsm.
#    They carry less of the half_B error. - No more sampler variants, per the B3b report §7. - A
#    seed repeat is not warranted while supported configuration levers remain.
#  Hypothesis: The JS term is what buys B3a's view invariance, and at lambda 0.3 it is
#    under-weighted: 2.5-4.5 % of the train loss, and JS fell from 0.0344 to 0.0038 by epoch 8 (B3a
#    metrics.jsonl). The JS gradient is concentrated on pairs whose views disagree. These are
#    typically a heavily degraded noisy/online view called spoof while its twin or the other
#    augmented view is called bona, which is the training-time analogue of the saturated noisy-bona
#    core. Raising lambda to 1.0 roughly triples the pull of those degraded views toward their
#    twin's posterior. That should move noisy bona out of the saturated spoof region and improve
#    noisy ranking (EER), not just the threshold. Clean behaviour and the global operating point
#    should stay put, because the CE weights and the class prior are unchanged. If the core is made
#    of clips where both views are confidently wrong, JS cannot reach it, and the falsifier below
#    will show it: the core share stays flat while JS falls.
#  Expected signature: Merge vs B3a-top5 (half_B WF1 93.06); ep8 vs B3a-ep8 (92.94): - Ranking:
#    mean noisy EER below 9.16 on the merge (9.01 on ep8), by at least 0.3. Full-set SNR-0 EER
#    below 14.67 matched / 15.08 heldout. - Saturated core: noisy bona share at p_spoof >= 0.99
#    below 17.6 % (merge) and 19.8 % (ep8). Noisy bona false alarms below 180 of 782. English noisy
#    false alarms not above 91. - Recall: heldout R_bona above 74.94 and matched R_bona above
#    79.03, with R_spoof within 0.5 of 99.38 / 99.06. - Unchanged: clean F1 within 0.5 of 97.48;
#    best global logit within +-1 of 0 (B3a merge -0.15). - Telemetry: unweighted JS below B3a's at
#    most epochs, and below 0.0038 at epoch 8. CE per epoch roughly at B3a's level (0.3945 at epoch
#    1 down to 0.0283 at epoch 8). Epoch-8 dev loss not above 0.1722 (same CE weights, so
#    comparable). - Headline: merge half_B WF1 above 93.06, with most of the gain on heldout and
#    matched.
#  Derivation: python3 -I on
#    SLS_setup/exp/B3a_qwen17_rtc_musan_loud23_cos8_lr2.5e6_cjs03_s1234_epoch8_bs8_20261009214846/metrics.jsonl
#    (b3.ce, b3.js per epoch): B3a metrics.jsonl: epoch, CE, JS, 0.3*JS share of train loss
#    (actual), 1.0*JS share if CE/JS unchanged 1 0.3945 0.0344 2.5% 8.0% mini wf1 90.17 eer_noisy
#    13.14 2 0.1867 0.0214 3.3% 10.3% mini wf1 91.64 eer_noisy 11.56 3 0.1176 0.0151 3.7% 11.4%
#    mini wf1 91.39 eer_noisy 11.49 4 0.0842 0.0113 3.9% 11.9% mini wf1 91.52 eer_noisy 10.80 5
#    0.0642 0.008 3.6% 11.1% mini wf1 92.52 eer_noisy 11.16 6 0.0452 0.0065 4.2% 12.6% mini wf1
#    92.87 eer_noisy 10.09 7 0.0328 0.0051 4.5% 13.5% mini wf1 92.36 eer_noisy 10.40 8 0.0283
#    0.0038 3.9% 11.9% mini wf1 92.14 eer_noisy 10.28 Header format check: python3 -I -c
#    'print(f"{1.0:g}", f"{0.3:g}")' -> "1 0.3", so the trainer prints "lambda_js=1" (train.py line
#    630 uses {args.consistency_lambda:g}); the expect regex therefore matches "lambda_js=1 ", not
#    "1.0". Steps unchanged: --batch_size 8 pairs (16 clips/step), 8 epochs, same 75792 cosine
#    steps as B3a/B3b ("Warmup-cosine: 3790 warmup / 75792 steps" in the B3b report).
#  Eval note: Evaluate both readouts with --loudness_norm --loudness_norm_lufs -23 (read from
#    config.yaml): the top-5 merge, which is the objective, and epoch_8. Checkpoints are plain
#    ModelSLS state_dicts. Compare against B3a-top5 / B3a-ep8 (the current best) and the fixed
#    comparators B2f-top5 / B2f-ep8, with the paired-bootstrap CI at n 2000. Report: - mean noisy
#    EER and the full-set SNR-0 EER; - the half_B noisy bona share at p >= 0.99 / 0.999 and the
#    number of false alarms, split en / zh; - per-set R_bona / R_spoof; - the best global logit
#    threshold; - per-epoch CE, JS and the JS share of train_loss from metrics.jsonl (lambda is now
#    1.0, so train_loss = CE + 1.0*JS), compared with B3a's. This run isolates the divergence
#    weight from B3a's step / view confound. State explicitly which side of falsifier 1 it lands
#    on.
#  Falsification (pre-registered): delta top-5-merge half_B.wf1.wf1 vs B3a merge (93.06) > +0.5
#    with the paired-bootstrap CI excluding 0 and clean F1 drop <= 0.5 -> positive; within +-0.5 ->
#    null; below -0.5 -> negative. Wave rule against B3a-top5 = 93.06 on half_B: - Promote /
#    positive: delta merge > +0.5, the paired-bootstrap CI excluding 0, and a clean F1 drop <= 0.5.
#    - Null: delta within +-0.5. - Negative: delta below -0.5. Mechanism-level refutations: 1.
#    Weight is not the active ingredient: delta within +-0.5 AND merge noisy EER within +-0.3 of
#    9.16. Then B3a's gain came from the paired views and the doubled steps, not the divergence
#    weight; keep 0.3 and deprioritise js_emb. 2. Over-regularised: clean F1 drop > 0.5, or R_spoof
#    down > 0.5 on matched or heldout. 3. JS cannot reach the core: noisy bona share at p >= 0.99
#    not below 17.6 % while epoch-8 JS falls below 0.0038. The core is agree-but-wrong, so pursue a
#    different mechanism (SNR range / codec / SpecAugment), not js_emb. 4. Operating point shifted
#    rather than ranking improved: best global logit beyond +-1 together with noisy EER not below
#    9.16.
#
#   bash scripts/run_B3c.sh                                   # fresh run (the exploop supervisor launches it)
#   bash scripts/run_B3c.sh --resume exp/<run dir name>       # after a container restart
#   EXPLOOP_PRINT_ARGV=1 bash scripts/run_B3c.sh              # print the trainer argv, launch nothing
#
# Rendered from scripts/exploop/launcher_template.sh (same shape as scripts/run_B3a.sh). Extra
# arguments are appended to the trainer command line. Training runs under nohup; stdout/stderr go to
# <workdir>/<track>_<timestamp>.log and the per-epoch summary to <run dir>/logs/train.log.
set -euo pipefail

PY="${PY:-/root/.conda/envs/rtc-sdd/bin/python}"
TRACK="B3c_qwen17_rtc_musan_loud23_cos8_lr2.5e6_cjs10_s1234"
WORKDIR="/root/repos/rtc-sdd/Ghostbusters_team/SLS_setup"

ARGS=(
    --train_data_path /mnt/paml-research/RTCFake/data/wav/train
    --train_protocol /mnt/paml-research/RTCFake/data/train_label.txt
    --dev_data_path /mnt/paml-research/RTCFake/data/wav/dev
    --dev_protocol ../data/dev_noisy_sim/dev_label_excl_halfB.txt
    --ssl_name Qwen/Qwen3-ASR-1.7B
    --n_layers 24
    --batch_size 8
    --num_epochs 8
    --num_workers 64
    --use_rtc_aug
    --aug_noise_dirs ../data/augmentation_train/rnnoise ../data/augmentation_train/esc50
    --aug_rir_dirs ../data/augmentation_train/rirs
    --musan
    --musan_dir ../data/augmentation/musan
    --loudness_norm
    --loudness_norm_lufs -23
    --optim adamw
    --lr 2.5e-6
    --head_lr_mult 10
    --weight_decay 0.01
    --lr_scheduler warmup_cosine
    --warmup_frac 0.05
    --lr_min 5e-7
    --grad_clip 1.0
    --ema_decay 0.9995
    --local_eval_sets ../configs/local_eval_sets.yaml
    --earlystop_metric wf1
    --earlystop_epoch 99
    --keep_topk_by_wf1 7
    --keep_epochs 8
    --seed 1234
    --track "$TRACK"
    --consistency js
    --consistency_lambda 1.0
    --consistency_pairs both
)

if [ "${EXPLOOP_PRINT_ARGV:-0}" = "1" ]; then
    printf '%s\n' "${ARGS[@]}"
    exit 0
fi

if [ ! -x "$PY" ]; then
    echo "python not found: $PY (set PY=... to override)" >&2
    exit 1
fi
if ! command -v ffmpeg >/dev/null 2>&1; then
    echo "ffmpeg not found on PATH: the RTC codec augmentation would silently no-op. Reinstall it first." >&2
    exit 1
fi
if ! "$PY" -c "import pyloudnorm" >/dev/null 2>&1; then
    echo "pyloudnorm not importable by $PY: run '$PY -m pip install pyloudnorm==0.2.0' first." >&2
    exit 1
fi

cd "$WORKDIR"
LOG="${TRACK}_$(date +%Y%m%d%H%M%S).log"

nohup "$PY" -u -m b3wave.train "${ARGS[@]}" "$@" > "$LOG" 2>&1 &

PID=$!
echo "Started $TRACK (pid $PID)"
echo "Log:     $WORKDIR/$LOG"
echo "Follow:  tail -f $WORKDIR/$LOG"
echo "Stop:    kill $PID"
